-- 1: houyi-fat-injection
UPDATE products SET
  name = 'HOUYI حقنة التغذية الدقيقة - لتقديم الطعام السائل والمعلق',
  description = E'حقنة بلاستيكية شفافة مصممة لتقديم الأطعمة السائلة والمعلقة بدقة في أماكن محددة داخل الحوض. مثالية لتغذية المرجان والروبيان وصغار الأسماك.\n\nتسمح بالتحكم الدقيق في كمية الطعام المقدم وموقعه. تقلل هدر الطعام وتلوث الماء مقارنة بالصب العشوائي.\n\nسهلة التنظيف وقابلة لإعادة الاستخدام. مناسبة أيضاً لتقديم الأدوية السائلة بدقة.',
  specifications = '{"brand":"HOUYI","model":"Feeding Syringe","benefits":["تقديم دقيق للطعام في أماكن محددة","تقلل هدر الطعام وتلوث الماء","مثالية للمرجان والروبيان والصغار","مناسبة لتقديم الأدوية السائلة","شفافة لرؤية الكمية","سهلة التنظيف وإعادة الاستخدام"],"المادة":"بلاستيك شفاف (Syringe)","النوع":"حقنة تغذية","مناسب لـ":"تغذية دقيقة، مرجان، روبيان، أدوية سائلة","بلد المنشأ":"الصين","طريقة الاستخدام":"اسحب الطعام السائل في الحقنة. أدخل طرف الحقنة قرب المكان المطلوب. اضغط ببطء لتقديم الطعام. اغسل بعد كل استخدام.","تحذيرات":"لا تستخدم نفس الحقنة للطعام والأدوية. اغسل جيداً بعد كل استخدام. لا تقدم كميات كبيرة دفعة واحدة."}'::jsonb
WHERE id = 'houyi-fat-injection';

-- 2: houyi-tracheal-suction-cup
UPDATE products SET
  name = 'HOUYI ماصات تثبيت الأنابيب والخراطيم - عبوة متعددة',
  description = E'ماصات بلاستيكية مع حامل للأنابيب مصممة لتثبيت خراطيم الهواء وأنابيب الفلتر على زجاج الحوض. تبقي الخراطيم مرتبة وثابتة في مكانها.\n\nماصة قوية الالتصاق على الزجاج النظيف. حامل مرن يتسع لأقطار مختلفة من الأنابيب والخراطيم.\n\nعبوة متعددة القطع تكفي لتنظيم جميع خراطيم الحوض. قابلة لإعادة الاستخدام بعد التنظيف.',
  specifications = '{"brand":"HOUYI","model":"Tracheal Suction Cup","benefits":["تثبيت قوي على الزجاج النظيف","حامل مرن يتسع لأقطار مختلفة","تبقي الخراطيم مرتبة وثابتة","عبوة متعددة القطع اقتصادية","قابلة لإعادة الاستخدام","تمنع انفلات الخراطيم"],"المادة":"بلاستيك مع ماصة مطاطية","النوع":"ماصات تثبيت","مناسب لـ":"تثبيت خراطيم الهواء، أنابيب الفلتر، أسلاك السخانات","بلد المنشأ":"الصين","طريقة الاستخدام":"نظّف الزجاج وجفّفه. اضغط الماصة بقوة على الزجاج. ادفع الخرطوم في الحامل حتى يستقر.","تحذيرات":"الزجاج المتسخ يضعف الالتصاق. استبدل الماصات إذا فقدت مرونتها. بلّلها قبل الالصاق لتحسين الالتصاق."}'::jsonb
WHERE id = 'houyi-tracheal-suction-cup';

-- 3: houyi-acrylic-pump-compartment
UPDATE products SET
  name = 'HOUYI حجرة مضخة أكريليك شفافة - قابلة للتوصيل | حجم متوسط',
  description = E'حجرة أكريليك شفافة مصممة لحماية المضخة الغاطسة وتنظيم خراطيمها. يمكن تثبيتها داخل حجرة الفلتر الخلفي أو السومب.\n\nالأكريليك الشفاف يسمح بمراقبة عمل المضخة دون فتح الحجرة. فتحات مصممة لتوصيل الخراطيم بسهولة.\n\nحجم متوسط مناسب لمعظم المضخات الغاطسة القياسية.',
  specifications = '{"brand":"HOUYI","model":"Acrylic Pump Compartment","benefits":["أكريليك شفاف لمراقبة عمل المضخة","فتحات مصممة لتوصيل الخراطيم","تحمي المضخة وتنظم الخراطيم","حجم متوسط يناسب المضخات القياسية","تثبيت سهل في الفلتر أو السومب","تصميم نظيف ومرتب"],"المادة":"أكريليك شفاف","الحجم":"متوسط","النوع":"حجرة مضخة","مناسب لـ":"حماية المضخات الغاطسة، فلتر خلفي، سومب","بلد المنشأ":"الصين","طريقة الاستخدام":"ضع الحجرة في المكان المخصص. أدخل المضخة. وصّل الخراطيم عبر الفتحات المخصصة.","تحذيرات":"تأكد من توافق حجم الحجرة مع المضخة. نظّف من الطحالب بانتظام. لا تعرّض لأشعة الشمس المباشرة."}'::jsonb
WHERE id = 'houyi-acrylic-pump-compartment';

-- 4: houyi-mesh
UPDATE products SET
  name = 'HOUYI شبكة عزل ستانلس ستيل (Wire Mesh) - متينة ومقاومة للصدأ',
  description = E'شبكة معدنية من الستانلس ستيل عالي الجودة مصممة لعزل مناطق في الحوض أو تغطية فتحات الفلتر. مقاومة للصدأ بالكامل في البيئة المائية.\n\nفتحات الشبكة تسمح بتدفق الماء بحرية مع منع مرور الأسماك والروبيان. يمكن ثنيها وقصها بالمقص المعدني لتناسب أي شكل.\n\nأقوى وأطول عمراً من الشبكات البلاستيكية والقماشية. مناسبة لعزل مناطق الترشيح والتصريف.',
  specifications = '{"brand":"HOUYI","model":"Wire Mesh","benefits":["ستانلس ستيل مقاوم للصدأ بالكامل","متينة وتدوم لسنوات طويلة","تسمح بتدفق الماء بحرية","قابلة للثني والقص لأي شكل","أقوى من الشبكات البلاستيكية","مناسبة للعزل وتغطية الفتحات"],"المادة":"Stainless Steel Wire Mesh","النوع":"شبكة عزل معدنية","مناسب لـ":"عزل مناطق الحوض، تغطية فتحات الفلتر، حماية النباتات","بلد المنشأ":"الصين","طريقة الاستخدام":"قص بالحجم المطلوب بمقص معدني. اثنِ الحواف لتجنب الأطراف الحادة. ثبّت بالماصات أو اللاصق.","تحذيرات":"اثنِ الحواف الحادة لحماية الأسماك. استخدم قفازات عند القص. تحقق من عدم وجود أسلاك بارزة."}'::jsonb
WHERE id = 'houyi-mesh';

-- 5: houyi-sucker-buckle
UPDATE products SET
  name = 'HOUYI ماصات تثبيت السخانات والأنابيب - نوع المشبك (Buckle)',
  description = E'ماصات تثبيت بنظام مشبك (Buckle) مصممة لتثبيت السخانات وأنابيب الفلتر على زجاج الحوض. المشبك يحيط بالأنبوب ويقفله في مكانه بإحكام.\n\nأقوى من الماصات العادية لأن المشبك يغلق حول الأنبوب تماماً فلا ينفلت مع اهتزازات المضخة أو حركة الأسماك الكبيرة.\n\nمناسبة للأنابيب والسخانات ذات الأقطار المختلفة بفضل مرونة المشبك.',
  specifications = '{"brand":"HOUYI","model":"Sucker Buckle","benefits":["نظام مشبك يقفل الأنبوب بإحكام","أقوى من الماصات العادية","لا ينفلت مع الاهتزازات أو حركة الأسماك","مناسب لأقطار مختلفة","ماصة قوية تلتصق بالزجاج","سهل التركيب والفك"],"المادة":"بلاستيك + ماصة مطاطية","النوع":"ماصة بمشبك (Buckle Type)","مناسب لـ":"تثبيت السخانات، أنابيب الفلتر، الأنابيب الكبيرة","بلد المنشأ":"الصين","طريقة الاستخدام":"نظّف الزجاج. اضغط الماصة على الزجاج. افتح المشبك وأدخل الأنبوب أو السخان. أغلق المشبك.","تحذيرات":"نظّف الزجاج لضمان الالتصاق. استبدل إذا فقدت الماصة مرونتها. تحقق من الثبات بانتظام."}'::jsonb
WHERE id = 'houyi-sucker-buckle';

-- 6: houyi-tracheal-suction
UPDATE products SET
