-- 7: houyi-hose-clamp
UPDATE products SET
  name = 'HOUYI مشبك خراطيم الفلتر الآمن (Hose Clamp) - يمنع التسريب',
  description = E'مشبك معدني أو بلاستيكي يُثبّت على نقاط توصيل خراطيم الفلتر لمنع انفلاتها وتسريب الماء. أداة أمان بسيطة لكنها ضرورية لمنع كوارث التسريب.\n\nسهل التركيب - يُوضع على الخرطوم عند نقطة التوصيل بالفلتر أو المضخة ويُشدّ لإحكام الختم.\n\nمناسب لخراطيم الفلاتر الخارجية بأقطار مختلفة. عبوة متعددة القطع لتأمين جميع نقاط التوصيل.',
  specifications = '{"brand":"HOUYI","model":"Hose Clamp","benefits":["يمنع انفلات الخراطيم وتسريب الماء","أداة أمان ضرورية للفلاتر الخارجية","سهل التركيب والشدّ","مناسب لأقطار خراطيم مختلفة","يحكم ختم نقاط التوصيل","عبوة متعددة القطع"],"المادة":"معدن / بلاستيك متين","النوع":"مشبك خراطيم (Hose Clamp)","مناسب لـ":"خراطيم الفلاتر الخارجية، نقاط التوصيل","بلد المنشأ":"الصين","طريقة الاستخدام":"ادخل الخرطوم على منفذ الفلتر. ضع المشبك فوق نقطة التوصيل. اشدّ المشبك بإحكام معتدل.","تحذيرات":"لا تشدّ أكثر من اللازم لتجنب تلف الخرطوم. تحقق من الإحكام بعد كل صيانة. استبدل المشابك الصدئة أو المكسورة فوراً."}'::jsonb
WHERE id = 'houyi-hose-clamp';
